import{_ as s,o as n,c as p,a3 as r}from"./chunks/framework.BwzYn71E.js";const d=JSON.parse('{"title":"自动配平讲解-对轴配音稿","description":"","frontmatter":{"translationSource":{"title":"自动配平讲解-对轴配音稿","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=w6t5TkRbD3DI8kV9oOGObx","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/automatic-balancing-voiceover-script"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/automatic-balancing-voiceover-script"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/automatic-balancing-voiceover-script"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/automatic-balancing-voiceover-script"}]]},"headers":[],"relativePath":"zh/automatic-balancing-voiceover-script.md","filePath":"zh/page-w6t5TkRbD3DI8kV9oOGObx.md"}'),e={name:"zh/automatic-balancing-voiceover-script.md"};function l(o,a,c,t,k,g){return n(),p("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="自动配平讲解-对轴配音稿" tabindex="-1">自动配平讲解-对轴配音稿 <a class="header-anchor" href="#自动配平讲解-对轴配音稿" aria-label="Permalink to &quot;自动配平讲解-对轴配音稿&quot;">​</a></h1><blockquote><p>源页面 ID：<code>w6t5TkRbD3DI8kV9oOGObx</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=w6t5TkRbD3DI8kV9oOGObx" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-T0udFqQDsi3HUVmGZAEktB"></span></p><h2 id="对轴配音稿" tabindex="-1">对轴配音稿 <a class="header-anchor" href="#对轴配音稿" aria-label="Permalink to &quot;对轴配音稿&quot;">​</a></h2><p><span id="source-block-TdmTliJ9pTQA0kZdGXquc2"></span></p><h3 id="_0-为什么要自动配平" tabindex="-1">0. 为什么要自动配平 <a class="header-anchor" href="#_0-为什么要自动配平" aria-label="Permalink to &quot;0. 为什么要自动配平&quot;">​</a></h3><p>在1.4版本伊始，气体工业的加入带来两位大人：</p><p><strong>&lt;（°0°）&gt;</strong><span class="mark-red"><strong>灼铜大人</strong></span><strong>和</strong><span class="mark-green"><strong>重息壤大人</strong></span><strong>\\（°0°）/</strong></p><p>我的天哪<span class="mark-red">灼铜大人</span>售价70调度券，超凡脱俗的复杂工艺震撼人心！</p><p>经过各路up各显神通的计算，</p><p>我们现在知道所谓最高产能就是多多地做<span class="mark-red">灼铜大人</span>和<span class="mark-green">重息壤大人</span>，加上两位前朝显贵<span class="mark-orange">中容武陵电池大人</span>和<span class="mark-blue">芽针针剂，呃，小人</span>，</p><p>最好是一点<span class="mark-red">铜</span>和<span class="mark-green">息壤</span>都不要剩下，<span class="mark-orange">源矿</span>和<span class="mark-blue">蓝铁</span>也是一样。</p><p>为了做到这一点，up们先是给出了14.4<span class="mark-red">灼铜零件</span>24<span class="mark-green">重息壤</span>的配平组合，然后给出了更极限的14.2<span class="mark-red">灼铜零件</span>26<span class="mark-green">重息壤</span>的配平组合，后者已经非常非常接近理论解！</p><p>呃但是我只是一个普通玩家，比起压榨产能我想说：</p><p>要吃药怎么办？</p><p>矿没开齐怎么办？</p><p>不想拉净水节点怎么办？</p><p>谷地没开超库存传输怎么办？</p><p>欸，普通玩家还要求这多，那为什么不用剩下原料更多的低产量产线呢？</p><p>那咋了，我就是想利用掉所有原料又高产还要能满足这些要求，不行吗？</p><p><strong>于是经过我们的努力，自动配平产线就此诞生。</strong></p><hr><p><span id="source-block-A6YtcrIbSsShc6LyLEsu02"></span></p><h3 id="_1-局部自动配平" tabindex="-1">1. 局部自动配平 <a class="header-anchor" href="#_1-局部自动配平" aria-label="Permalink to &quot;1. 局部自动配平&quot;">​</a></h3><p>一上来就理解四种原料自动配平成四种产物也太难了，我们先只制作灼铜和重息壤。</p><p>虽然<span class="mark-red">灼铜零件</span>和<span class="mark-green">重息壤</span>的配方十分复杂，但是先不要被配方吓到，归根结底，它们终究只是使用同样的两种原料：<span class="mark-red"><strong>铜</strong></span>和<span class="mark-green"><strong>息壤</strong></span>。</p><p>让我们忽略掉中间的弯弯绕绕吧。</p><p>现在请想象这样的一个账号：</p><ul><li><p><span class="mark-red">铜</span>产量 <u><strong>325</strong></u>/min；</p></li><li><p><span class="mark-green">息壤和息壤气</span>产量拉满；</p></li></ul><p>我们只做<span class="mark-red">灼铜</span>和<span class="mark-green">重息壤</span>，此时的产出是这样的：</p><p>现在把剩余矿点都连上，<span class="mark-red">铜</span>产量提高到 510/min。</p><p>多出来的这些<span class="mark-red">铜</span>怎么消耗掉呢？如果我们增加<span class="mark-green">重息壤</span>产量，</p><p>欸不对不对，怎么<span class="mark-red">铜</span>消耗还变少了！那增加<span class="mark-red">灼铜</span>产量呢？</p><p>欸对了对了，这样一来多出来的<span class="mark-red">铜</span>就全部被消耗掉了。</p><p><strong>也就是说为了配平多出来的</strong><span class="mark-red"><strong>铜</strong></span><strong>，</strong><span class="mark-red"><strong>灼铜</strong></span><strong>产量要增加而</strong><span class="mark-green"><strong>重息壤</strong></span><strong>产量则随之减少。（考虑单独占据画面）</strong></p><p>但是要自动配平的话，得让产线随着<span class="mark-red">铜</span>增加自发地增加<span class="mark-red">灼铜</span>产量、减少<span class="mark-green">重息壤</span>产量。</p><p>这该怎么做到呢？这里先给出结论：</p><ul><li><p><span class="mark-green"><strong>息壤</strong></span><strong>：先喂饱</strong><span class="mark-red"><strong>灼铜产线</strong></span><strong>，剩下的给</strong><span class="mark-green"><strong>重息壤产线</strong></span><strong>。</strong></p></li><li><p><span class="mark-red"><strong>铜</strong></span><strong>：先喂饱</strong><span class="mark-green"><strong>重息壤产线</strong></span><strong>，剩下的给</strong><span class="mark-red"><strong>灼铜产线</strong></span><strong>。</strong></p></li></ul><hr><p><span id="source-block-jZOd3dBgugDu3i35khYrim"></span></p><h3 id="_2-供料顺序不能反" tabindex="-1">2. 供料顺序不能反 <a class="header-anchor" href="#_2-供料顺序不能反" aria-label="Permalink to &quot;2. 供料顺序不能反&quot;">​</a></h3><p>为什么必须是“<span class="mark-green">息壤</span>先喂饱<span class="mark-red">灼铜产线</span>，<span class="mark-red">铜</span>先喂饱<span class="mark-green">重息壤产线</span>”？我们一个个来看。</p><p><span id="source-block-cYHhsyKNC4L0Lf3Ndagu19"></span></p><h4 id="如果灼铜产线的息壤不够" tabindex="-1">如果<span class="mark-red">灼铜产线</span>的<span class="mark-green">息壤</span>不够 <a class="header-anchor" href="#如果灼铜产线的息壤不够" aria-label="Permalink to &quot;如果&lt;span class=&quot;mark-red&quot;&gt;灼铜产线&lt;/span&gt;的&lt;span class=&quot;mark-green&quot;&gt;息壤&lt;/span&gt;不够&quot;">​</a></h4><p>让我们回到上一节的例子中，刚连上矿点的时候：</p><p>尝试增加<span class="mark-red">灼铜</span>产量，但是<span class="mark-green">息壤</span>供应不够，增加到一半卡住了！</p><p>这时我们可以看到，多出来的<span class="mark-red">铜</span>没有被全部消耗掉。</p><p><strong>于是我们得到结论：想利用掉增加的</strong><span class="mark-red"><strong>铜</strong></span><strong>，必须先用</strong><span class="mark-green"><strong>息壤</strong></span><strong>喂饱</strong><span class="mark-red"><strong>灼铜产线</strong></span><strong>，保证它</strong><span class="mark-green"><strong>息壤</strong></span><strong>足够。</strong></p><p><span id="source-block-fX5Pw22uV8xI3PunEWO21N"></span></p><h4 id="如果重息壤产线的铜不够" tabindex="-1">如果<span class="mark-green">重息壤产线</span>的<span class="mark-red">铜</span>不够 <a class="header-anchor" href="#如果重息壤产线的铜不够" aria-label="Permalink to &quot;如果&lt;span class=&quot;mark-green&quot;&gt;重息壤产线&lt;/span&gt;的&lt;span class=&quot;mark-red&quot;&gt;铜&lt;/span&gt;不够&quot;">​</a></h4><p>类似的，我们增加<span class="mark-green">息壤</span>，然后尝试增加<span class="mark-green">重息壤</span>产量。</p><p>结果是类似的，因为<span class="mark-green">重息壤产线</span>的<span class="mark-red">铜</span>供应不足，所以我们没花光增加的<span class="mark-green">息壤</span>。</p><p>那么结果和<span class="mark-red">灼铜产线</span>缺<span class="mark-green">息壤</span>的情形非常类似了，想要利用掉增加的<span class="mark-green">息壤</span>，必须先用<span class="mark-red">铜</span>喂饱<span class="mark-green">重息壤产线</span>，保证它<span class="mark-red">铜</span>足够。</p><p>到这里我们已经回答了为什么必须是“<span class="mark-green">息壤</span>先喂饱<span class="mark-red">灼铜产线</span>，<span class="mark-red">铜</span>先喂饱<span class="mark-green">重息壤产线</span>”，但是我们给出的结论还有一部分——“剩下的<span class="mark-green">息壤</span>给<span class="mark-green">重息壤产线</span>，剩下的<span class="mark-red">铜</span>给<span class="mark-red">灼铜产线</span>”</p><p>我们试想如果只做<span class="mark-green">重息壤</span>，那<span class="mark-green">重息壤产线</span>自己当然用不掉这么多<span class="mark-red">铜</span>，</p><p>这些剩余的<span class="mark-red">铜</span>就需要让<span class="mark-red">灼铜产线</span>来消耗掉。</p><p>可以看出，如果我们想要所有原料被利用干净，就一定需要一条产线来消耗掉剩余的原料。<br> 方便起见，这种专门吃“其他产线用剩下的某种原料”的产线，我们叫它：</p><p><strong>末端产线</strong></p><p>那么<span class="mark-red">灼铜产线</span>可以称为<span class="mark-red">铜</span>这一原料的末端产线，也就是说<span class="mark-red">灼铜产线</span>是消耗<span class="mark-red">铜</span>的产线里最末尾的产线。</p><p>类似的，只做<span class="mark-red">灼铜</span>用不掉的<span class="mark-green">息壤</span>则是由<span class="mark-green">重息壤产线</span>来消耗掉，那么<span class="mark-green">重息壤产线</span>可以称为<span class="mark-green">息壤</span>这一原料的末端产线。</p><hr><p><span id="source-block-C4dJPcSew5kq8oedDEKmS7"></span></p><h3 id="_3-更多原料" tabindex="-1">3. 更多原料！？ <a class="header-anchor" href="#_3-更多原料" aria-label="Permalink to &quot;3. 更多原料！？&quot;">​</a></h3><p>截至目前，我们处理了两种原料<span class="mark-green"></span><span class="mark-red">铜 </span><span class="mark-green">息壤 </span>两种产物 <span class="mark-red">灼铜 </span><span class="mark-green">重息壤</span></p><p>但是1.5版本我们还有另外两种原料 <span class="mark-orange">源矿</span> <span class="mark-blue">蓝铁 </span>另外两种产物<span class="mark-blue"></span><span class="mark-orange">中电</span><span class="mark-blue"> 小药</span></p><p>现在我们把他们加进来：</p><p>是不是一下子眼花缭乱了？别心急，别忘了我们的目的是让所有原料都被消耗，所以每一种原料都需要一条产线来消耗掉其他产线用剩下的部分——<strong>也就是说，我们可以让原料和末端一一对应！</strong></p><p>可能有细心的观众已经发现了，在之前的讲解中我们会用特定颜色来表示原料和产物，其实相同的颜色就表示原料与之对应的末端：</p><p><span class="mark-red">铜-灼铜 </span><span class="mark-green">息壤-重息壤 </span><span class="mark-orange">源矿-中电 </span><span class="mark-blue">蓝铁-小药</span></p><p>在之前的讲解中我们已经知道了消耗<span class="mark-red">铜</span>为主的<span class="mark-red">灼铜产线</span>是<span class="mark-red">原料铜</span>的末端产线，消耗<span class="mark-green">息壤</span>为主的<span class="mark-green">重息壤产线</span>是<span class="mark-green">原料息壤</span>的末端产线，</p><p>那么，消耗<span class="mark-orange">源矿</span>为主的<span class="mark-orange">中电产线</span>就是<span class="mark-orange">原料源矿</span>的末端产线，消耗<span class="mark-blue">蓝铁</span>为主的<span class="mark-blue">小药产线</span>就是<span class="mark-blue">原料蓝铁</span>的末端产线！</p><p>同样的，和<span class="mark-red">灼铜</span><span class="mark-green">重息壤</span>类似，为了让<span class="mark-orange">中电产线</span>可以顺利吃完<span class="mark-orange">源矿</span>以及让小药产线可以顺利吃完蓝铁，我们需要让<span class="mark-orange">中电产线</span>除了<span class="mark-orange">源矿</span>之外的其他原料都供应充足，也就是中电产线所需要的<span class="mark-green">息壤</span>和蓝铁都被优先供满，</p><p>而<span class="mark-blue">小药产线</span>只吃<span class="mark-blue">蓝铁</span>，所以就没有什么需要供应充足的地方了</p><p>我们可以把这些整理成一张表格：</p><p><span id="source-block-2eRoxdJJTl9mAKahWoUH50"></span></p><h3 id="_4-更多样的末端" tabindex="-1">4. 更多样的末端 <a class="header-anchor" href="#_4-更多样的末端" aria-label="Permalink to &quot;4. 更多样的末端&quot;">​</a></h3><p>那末端只能是一种产物吗？当然不是！</p><p>比如在 1.5 智能最大毛产中，当<span class="mark-red">赫铜</span>未满仓时，<span class="mark-red">赫铜</span>和<span class="mark-red">灼铜</span>产出保持 1:2。这时<span class="mark-red">铜末端</span>就不是单纯的<span class="mark-red">灼铜</span>，而是<span class="mark-red">“</span><span class="mark-red"><strong>1:2 的赫铜和灼铜”</strong></span><strong>。</strong></p><p>其实可以把多种产物组合成的末端看成是一个自定义配方的产物，那就和前面的单产物作为末端的情形一样了。</p><p>引入了组合产物作为末端后，我们能得到更多种产物了！或许这条路的尽头，我们能抵达<strong>全物品-自动配平</strong>的终极......</p><hr><p><span id="source-block-dLN8xGfLLH66LVRJpqSROR"></span></p><h3 id="_5-小结" tabindex="-1">5. 小结 <a class="header-anchor" href="#_5-小结" aria-label="Permalink to &quot;5. 小结&quot;">​</a></h3><p>让我们来整理下目前的内容：</p><p>整套自动配平，只需要记住两点：</p><ol><li><p>一种原料对应一种末端，就像是<span class="mark-red">铜</span>和<span class="mark-green">息壤</span>分别对应能消耗完<span class="mark-red">铜</span>的<span class="mark-red">灼铜</span>和能消耗完<span class="mark-green">息壤</span>的<span class="mark-green">重息壤</span>。当然了，末端可以是组合的产物，像是上一节提到的<span class="mark-red">“1:2 的赫铜和灼铜”</span>作为<span class="mark-red">铜末端</span>。</p></li><li><p>每种原料都先喂饱其他用到这重原料产线，然后剩下的原料才给末端，比如<span class="mark-red">铜</span>先喂饱<span class="mark-green">重息壤产线</span>确保<span class="mark-green">重息壤产线</span>能顺利消耗完<span class="mark-green">息壤</span>然后剩下的<span class="mark-red">铜</span>给到作为<span class="mark-red">铜末端</span>的<span class="mark-red">灼铜产线</span>——五个字来说就是“<strong>先供非末端</strong>”，今后的涉及到自动配平的内容中我们将反复引用这五个字。</p></li></ol><p>“<strong>先供非末端</strong>”就是自动配平的铁律了，接下来我们用游戏中的具体结构来实现“<strong>先供非末端</strong>”。</p><hr><p><span id="source-block-809wjGnxF7cyPOuIKsbB9U"></span></p><h3 id="_6-回到实际的产线中去" tabindex="-1">6. 回到实际的产线中去 <a class="header-anchor" href="#_6-回到实际的产线中去" aria-label="Permalink to &quot;6. 回到实际的产线中去&quot;">​</a></h3><p>我们先考虑最简单的蓝铁，使用蓝铁的产线有中电产线和小药产线，其中小药产线负责保证蓝铁被消耗完，所以小药是蓝铁的末端，我们需要先供满不是蓝铁的末端产线的中电产线。</p><p>这样一来，只有中电产线供满了蓝铁块，蓝铁才会溢出到箱子里进入仓库，然后做成小药。</p><p>当然了，事实上还有相当多的办法来实现我们所需要的“先供xx再供xx”，而之后我们的产线发布视频中都会附带“如何做到先供非末端”的讲解。例如在大家比较熟悉的1.5版本最大毛产的视频（画面给到1.5版本最大毛产的封面）所采用的“空仓-加压”这一办法我们在后续会补发一个讲解视频进行讲解。之后将发布的迭代后产线则采用了“满仓-震荡”、“满仓-溢流”、“空仓-直连”、“定量取货口”，届时也会同步有讲解视频，希望观众们能通过我们的设计学习到更多基建思路并运用到自己的基建之中！</p><p><span id="source-block-60kuKbNnWvd4OISdYiWDGc"></span></p><h3 id="_7-为什么支持自行添加产线" tabindex="-1">7. 为什么支持自行添加产线？ <a class="header-anchor" href="#_7-为什么支持自行添加产线" aria-label="Permalink to &quot;7. 为什么支持自行添加产线？&quot;">​</a></h3><p>在视频的结尾我们来讲点简单的放松一下吧，</p><p>还记得视频开头所说的“普通玩家需求”吗？</p><p>到目前为止我们所讲述的大部分内容都是自动配平产线如何实现自动配平。但如果手动加了一条新产线，自动配平产线会怎么处理这个新产线的原料消耗？</p><p>其实可以把自行添加的产线所消耗的原料当成没有进入自动配平系统，就像没开的矿点一样。去掉这部分被使用的原料后，自动配平产线会把剩余的原料尽数转化为我们所希望得到的产物。</p><p><strong>于是，既要又要的狂想，就这样实现了。</strong></p><p>但是目前的自动配平事实上仍有极限，让我们把这个作为思考题：<br> 自行添加产线到什么程度，或者说什么样的原料比例，自动配平产线将无法将剩余原料完全配平？</p><hr><p>那么产线的自动配平/自适应讲解到这里就结束了</p><p>希望对大家有所启发</p></div>',1)])])}const i=s(e,[["render",l]]);export{d as __pageData,i as default};
